import { useState } from "react";

const SAMPLE_TAGS = ["React", "Spring", "Java", "SQL", "Docker", "Redis", "JPA", "TypeScript", "AWS", "Kubernetes"];

const SAMPLE_DOCS = [
  { id: 1, title: "Spring Boot 시작하기", tags: ["Spring", "Java"] },
  { id: 2, title: "React 훅 완전 정복", tags: ["React", "TypeScript"] },
  { id: 3, title: "JPA 연관관계 매핑", tags: ["JPA", "Java", "SQL"] },
  { id: 4, title: "Docker 컨테이너 배포", tags: ["Docker", "AWS"] },
  { id: 5, title: "Redis 캐싱 전략", tags: ["Redis", "Spring"] },
  { id: 6, title: "커서 기반 페이징 구현", tags: ["SQL", "Spring", "JPA"] },
  { id: 7, title: "Kubernetes 오케스트레이션", tags: ["Kubernetes", "Docker"] },
  { id: 8, title: "TypeScript 제네릭 활용", tags: ["TypeScript", "React"] },
];

export default function DocuTag() {
  const [search, setSearch] = useState("");
  const [selectedTags, setSelectedTags] = useState([]);
  const [showWrite, setShowWrite] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newTags, setNewTags] = useState([]);
  const [docs, setDocs] = useState(SAMPLE_DOCS);

  const toggleTag = (tag) => {
    setSelectedTags((prev) =>
      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
    );
  };

  const filteredDocs = docs.filter((doc) => {
    const matchSearch = doc.title.toLowerCase().includes(search.toLowerCase());
    const matchTags =
      selectedTags.length === 0 ||
      selectedTags.every((t) => doc.tags.includes(t));
    return matchSearch && matchTags;
  });

  const handleWrite = () => {
    if (!newTitle.trim()) return;
    setDocs((prev) => [
      { id: Date.now(), title: newTitle, tags: newTags },
      ...prev,
    ]);
    setNewTitle("");
    setNewTags([]);
    setShowWrite(false);
  };

  return (
    <div style={{ fontFamily: "'Noto Sans KR', 'Pretendard', sans-serif", minHeight: "100vh", background: "#0f0f11", color: "#e8e6e1" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;700&display=swap');

        * { box-sizing: border-box; margin: 0; padding: 0; }

        .navbar {
          position: sticky; top: 0; z-index: 100;
          background: #0f0f11ee;
          backdrop-filter: blur(12px);
          border-bottom: 1px solid #2a2a2f;
          padding: 14px 32px;
          display: flex; align-items: center; gap: 12px;
        }

        .logo {
          font-size: 18px; font-weight: 700;
          color: #c8f542; letter-spacing: -0.5px;
          margin-right: 16px; white-space: nowrap;
        }

        .search-wrap {
          flex: 1; display: flex; align-items: center;
          background: #1a1a1f; border: 1px solid #2a2a2f;
          border-radius: 8px; overflow: hidden;
          transition: border-color 0.2s;
        }
        .search-wrap:focus-within { border-color: #c8f542; }

        .search-input {
          flex: 1; background: transparent; border: none; outline: none;
          color: #e8e6e1; padding: 9px 14px; font-size: 14px;
          font-family: inherit;
        }
        .search-input::placeholder { color: #555; }

        .btn-search {
          background: #c8f542; border: none; cursor: pointer;
          padding: 9px 16px; font-size: 13px; font-weight: 700;
          color: #0f0f11; transition: background 0.15s;
        }
        .btn-search:hover { background: #d9ff55; }

        .btn-write {
          background: transparent; border: 1px solid #2a2a2f;
          color: #e8e6e1; padding: 8px 18px; border-radius: 8px;
          font-size: 13px; font-weight: 500; cursor: pointer;
          transition: all 0.15s; white-space: nowrap; font-family: inherit;
        }
        .btn-write:hover { border-color: #c8f542; color: #c8f542; }

        .tag-bar {
          padding: 14px 32px;
          display: flex; align-items: center; gap: 8px; flex-wrap: wrap;
          border-bottom: 1px solid #1e1e23;
        }

        .tag-bar-label {
          font-size: 11px; color: #555; font-weight: 600;
          letter-spacing: 0.5px; text-transform: uppercase;
          margin-right: 4px;
        }

        .tag-chip {
          padding: 4px 12px; border-radius: 100px;
          font-size: 12px; font-weight: 500; cursor: pointer;
          border: 1px solid #2a2a2f; background: transparent;
          color: #888; transition: all 0.15s; font-family: inherit;
        }
        .tag-chip:hover { border-color: #555; color: #ccc; }
        .tag-chip.active {
          background: #c8f542; border-color: #c8f542;
          color: #0f0f11; font-weight: 700;
        }

        .main { padding: 28px 32px; }

        .result-info {
          font-size: 12px; color: #444; margin-bottom: 20px;
        }
        .result-info span { color: #c8f542; font-weight: 600; }

        .grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
          gap: 16px;
        }

        .card {
          background: #16161a; border: 1px solid #222228;
          border-radius: 12px; padding: 20px;
          cursor: pointer; transition: all 0.2s;
          display: flex; flex-direction: column; gap: 12px;
        }
        .card:hover {
          border-color: #c8f54244;
          transform: translateY(-2px);
          box-shadow: 0 8px 32px #00000055;
        }

        .card-title {
          font-size: 15px; font-weight: 600; color: #e8e6e1;
          line-height: 1.4;
        }

        .card-tags {
          display: flex; flex-wrap: wrap; gap: 6px;
        }

        .card-tag {
          padding: 3px 10px; border-radius: 100px;
          font-size: 11px; font-weight: 500;
          background: #1e1e23; color: #888;
          border: 1px solid #2a2a2f;
        }
        .card-tag.highlight {
          background: #c8f54215; color: #c8f542;
          border-color: #c8f54244;
        }

        .empty {
          grid-column: 1 / -1;
          text-align: center; padding: 60px 0;
          color: #333; font-size: 14px;
        }

        /* Modal */
        .modal-overlay {
          position: fixed; inset: 0;
          background: #000000aa; backdrop-filter: blur(4px);
          z-index: 200; display: flex; align-items: center; justify-content: center;
        }

        .modal {
          background: #16161a; border: 1px solid #2a2a2f;
          border-radius: 16px; padding: 28px; width: 480px;
          display: flex; flex-direction: column; gap: 16px;
        }

        .modal-title { font-size: 16px; font-weight: 700; color: #e8e6e1; }

        .modal-input {
          background: #0f0f11; border: 1px solid #2a2a2f;
          border-radius: 8px; padding: 10px 14px;
          color: #e8e6e1; font-size: 14px; font-family: inherit;
          outline: none; transition: border-color 0.2s; width: 100%;
        }
        .modal-input:focus { border-color: #c8f542; }

        .modal-tag-label { font-size: 12px; color: #555; }

        .modal-tags {
          display: flex; flex-wrap: wrap; gap: 8px;
        }

        .modal-tag-btn {
          padding: 4px 12px; border-radius: 100px;
          font-size: 12px; cursor: pointer; font-family: inherit;
          border: 1px solid #2a2a2f; background: transparent; color: #888;
          transition: all 0.15s;
        }
        .modal-tag-btn:hover { border-color: #555; color: #ccc; }
        .modal-tag-btn.selected {
          background: #c8f54220; border-color: #c8f54288; color: #c8f542;
        }

        .modal-actions { display: flex; gap: 8px; justify-content: flex-end; }

        .btn-cancel {
          padding: 9px 20px; border-radius: 8px;
          background: transparent; border: 1px solid #2a2a2f;
          color: #888; font-size: 13px; cursor: pointer; font-family: inherit;
          transition: all 0.15s;
        }
        .btn-cancel:hover { border-color: #555; color: #ccc; }

        .btn-confirm {
          padding: 9px 20px; border-radius: 8px;
          background: #c8f542; border: none;
          color: #0f0f11; font-size: 13px; font-weight: 700;
          cursor: pointer; font-family: inherit; transition: background 0.15s;
        }
        .btn-confirm:hover { background: #d9ff55; }
        .btn-confirm:disabled { background: #2a2a2f; color: #444; cursor: not-allowed; }

        @media (max-width: 600px) {
          .grid { grid-template-columns: 1fr; }
          .navbar { padding: 12px 16px; }
          .tag-bar { padding: 12px 16px; }
          .main { padding: 20px 16px; }
        }
      `}</style>

      {/* Navbar */}
      <nav className="navbar">
        <span className="logo">DocuTag</span>
        <div className="search-wrap">
          <input
            className="search-input"
            placeholder="문서 제목 검색..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <button className="btn-search">검색</button>
        </div>
        <button className="btn-write" onClick={() => setShowWrite(true)}>+ 작성</button>
      </nav>

      {/* Tag filter bar */}
      <div className="tag-bar">
        <span className="tag-bar-label">태그</span>
        {SAMPLE_TAGS.map((tag) => (
          <button
            key={tag}
            className={`tag-chip${selectedTags.includes(tag) ? " active" : ""}`}
            onClick={() => toggleTag(tag)}
          >
            {tag}
          </button>
        ))}
      </div>

      {/* Main content */}
      <main className="main">
        <div className="result-info">
          <span>{filteredDocs.length}</span>개의 문서
          {selectedTags.length > 0 && <> · <span>{selectedTags.join(", ")}</span> 필터 적용 중</>}
        </div>
        <div className="grid">
          {filteredDocs.length === 0 ? (
            <div className="empty">검색 결과가 없습니다</div>
          ) : (
            filteredDocs.map((doc) => (
              <div className="card" key={doc.id}>
                <div className="card-title">{doc.title}</div>
                <div className="card-tags">
                  {doc.tags.map((tag) => (
                    <span
                      key={tag}
                      className={`card-tag${selectedTags.includes(tag) ? " highlight" : ""}`}
                    >
                      {tag}
                    </span>
                  ))}
                </div>
              </div>
            ))
          )}
        </div>
      </main>

      {/* Write modal */}
      {showWrite && (
        <div className="modal-overlay" onClick={() => setShowWrite(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-title">새 문서 작성</div>
            <input
              className="modal-input"
              placeholder="문서 제목"
              value={newTitle}
              onChange={(e) => setNewTitle(e.target.value)}
            />
            <div className="modal-tag-label">태그 선택</div>
            <div className="modal-tags">
              {SAMPLE_TAGS.map((tag) => (
                <button
                  key={tag}
                  className={`modal-tag-btn${newTags.includes(tag) ? " selected" : ""}`}
                  onClick={() =>
                    setNewTags((prev) =>
                      prev.includes(tag) ? prev.filter((t) => t !== tag) : [...prev, tag]
                    )
                  }
                >
                  {tag}
                </button>
              ))}
            </div>
            <div className="modal-actions">
              <button className="btn-cancel" onClick={() => setShowWrite(false)}>취소</button>
              <button className="btn-confirm" onClick={handleWrite} disabled={!newTitle.trim()}>
                작성
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
